// coupled-subsystem simulation sketch for: modeFRONTIER
const subs = [
  {name:'power', x:0.745, k:0.052},
  {name:'thermal', x:0.776, k:0.095},
  {name:'structural', x:0.615, k:0.121},
  {name:'control', x:0.335, k:0.075},
  {name:'comms', x:0.572, k:0.122},
];
for (let t = 0; t < 60; t++) {
  for (const s of subs) { s.x += s.k * (1 - s.x) - 0.015 * s.x; }
}
const fin = subs.map(s => +s.x.toFixed(4));
console.log(JSON.stringify({subsystems: subs.length, steps: 60,
  finalState: fin, converged: fin.every(v => v > 0 && v < 1.5),
  topic: 'modeFRONTIER'}));

